/*公共样式*/
.bgCss {
  background: url("/seat/skin/demo:0589eed14019486c/../images/bg.jpg") no-repeat;
  background-position: center center;
  background-size: cover;
}
.logoCss {
  background: url("/seat/skin/demo:0589eed14019486c/../images/logo.png") no-repeat;
  background-size: 100% 100%;
  position: absolute;
  top: 2rem;
  left: 2rem;
}
.btnBlue {
  background: #477eff;
  border: 1px solid #477eff;
  transition: all 0.3s;
}
.btnBlue:hover {
  background: #618df3;
  border: 1px solid #618df3;
}
.btnGray {
  background: #818ca2;
  border: 1px solid #818ca2;
  transition: all 0.3s;
}
.btnGray:hover {
  background: #9399a6;
  border: 1px solid #9399a6;
}
.btnYellow {
  box-shadow: none !important;
  background: #ff925a;
  border: 1px solid #ff925a;
  transition: all 0.3s;
}
.btnYellow:hover {
  background: #fa9f70;
  border: 1px solid #fa9f70;
}
.skin_btn {
  width: 9.2rem;
  line-height: 2rem;
  color: #fff;
  font-size: 0.9rem;
  text-align: center;
  display: block;
  cursor: pointer;
  border-radius: 3px;
  box-shadow: 0 0 5px #9ab7fc;
}
